    '        <div class="filter-pill active" onclick="filterByStatus(''all'')">Todos ($TotalCount)</div>',
    '        <div class="filter-pill" onclick="filterByStatus(''done'')">Hechas ($DoneCount)</div>',
    '        <div class="filter-pill" onclick="filterByStatus(''in_progress'')">En Progreso ($InProgressCount)</div>',
    '        <div class="filter-pill" onclick="filterByStatus(''spec_ready'')">Spec Lista ($SpecReadyCount)</div>',
    '        <div class="filter-pill" onclick="filterByStatus(''pending'')">Pendientes ($PendingCount)</div>',
    '      </div>',
    '',
