    '        <span style="font-weight: 600; color: var(--text-main);">Estados:</span>',
    '        <div class="legend-item"><span class="legend-dot dot-done"></span> Hecha (done)</div>',
    '        <div class="legend-item"><span class="legend-dot dot-in_progress"></span> En Progreso (in_progress)</div>',
    '        <div class="legend-item"><span class="legend-dot dot-spec_ready"></span> Spec Lista (spec_ready)</div>',
    '        <div class="legend-item"><span class="legend-dot dot-pending"></span> Pendiente (pending)</div>',
