    '        <div class="cmd-pill" onclick="copyText(''.\harness\sdd.ps1 -Action dashboard -Live'')">.\harness\sdd.ps1 -Action dashboard -Live</div>',
    '        <div class="cmd-pill" onclick="copyText(''.\harness\sdd.ps1 -Action verify-security'')">.\harness\sdd.ps1 -Action verify-security</div>',
    '        <div class="cmd-pill" onclick="copyText(''.\harness\sdd.ps1 -Action verify-performance'')">.\harness\sdd.ps1 -Action verify-performance</div>',
    '        <div class="cmd-pill" onclick="copyText(''.\harness\sdd.ps1 -Action export-compliance -Format pdf'')">.\harness\sdd.ps1 -Action export-compliance</div>',
    '        <div class="cmd-pill" onclick="copyText(''.\harness\sdd.ps1 -Action init-cicd'')">.\harness\sdd.ps1 -Action init-cicd</div>',
    '        <div class="cmd-pill" onclick="copyText(''.\harness\sdd.ps1 -Action pr-summary'')">.\harness\sdd.ps1 -Action pr-summary</div>',
    '        <div class="cmd-pill" onclick="copyText(''.\harness\sdd.ps1 -Action fix-markdown'')">.\harness\sdd.ps1 -Action fix-markdown</div>',
